import {e,field,editAttrs} from '../creative-kit/ui.js?v=0.21.0';
import {sourceDetails,familyMap} from '../shared/ancestry-ui.js?v=0.21.0';
import {FITS,MOMENT_LABELS} from './definitions.js?v=0.21.0';
import {allScenes,currentScene,needsReview} from './variants.js?v=0.21.0';
export function sceneHeader(w){return `<section class="scene-versions panel"><div class="section-head"><div><p class="eyebrow">ONE SITUATION, SEVERAL VERSIONS</p><h2>${e(w.scene.title)}</h2></div><div class="scene-picker"><label for="scene-picker">Open scene</label><select id="scene-picker" data-scene-switch>${allScenes(w).map(s=>`<option value="${e(s.id)}" ${s.id===w.scene.id?'selected':''}>${e(s.title)}${s.ancestry.parked?' · parked':''}</option>`).join('')}</select></div></div><div class="toolbar"><button data-action="vary" data-kind="person">Vary the person</button><button data-action="vary" data-kind="information">Vary the information</button><button data-action="vary" data-kind="moment">Vary the moment</button><button data-action="scene-details">Scene notes</button><button data-action="scene-family">Follow branches</button><a href="#scene-comparison">Compare fit ↓</a></div><p class="hint">Each variation keeps the original scene and interventions. Fit judgements belong to one scene; changed context needs another review.</p>${sourceDetails(w.scene.ancestry)}</section>`;}
export function variantDialog(w,kind){const m=w.moments.find(m=>m.id===w.selectedId),keys=kind==='person'?['actor','can']:kind==='information'?['knows','unknown']:['trigger','stakes'];return `<form id="variant-form" data-kind="${kind}" data-moment-id="${e(m.id)}"><p>Vary “${e(m.title)}” in a new scene. The current version stays intact.</p>${field('variation-title','Name the new scene',kind==='person'?'A different person':kind==='information'?'Different information':'A different moment','required')}${keys.map(key=>field(`variation-${key}`,MOMENT_LABELS[key],m[key],`data-variation-field="${key}"`)).join('')}${kind==='moment'?`<div class="field"><label for="variation-position">Position in the sequence</label><select id="variation-position">${w.moments.map((x,i)=>`<option value="${i}" ${x.id===m.id?'selected':''}>${i+1}: ${e(x.title)}</option>`).join('')}</select></div>`:''}${field('variation-reason','Why try this variation?','','','Which assumption or intervention might behave differently?')}<div class="toolbar"><button type="submit" class="primary">Create this scene</button><button type="button" data-action="close">Cancel</button></div></form>`;}
export function sceneDetails(w){return field('scene-title','Scene name',w.scene.title,editAttrs('scene',w.scene.id,'title'))+field('scene-changed','What differs?',w.scene.changed,editAttrs('scene',w.scene.id,'changed'))+field('scene-reason','Why explore this variation?',w.scene.reason,editAttrs('scene',w.scene.id,'reason'))+`<div class="toolbar"><button class="primary" data-action="close">Done</button><button data-action="scene-park" data-id="${e(w.scene.id)}">${w.scene.ancestry.parked?'Revive scene':'Park scene'}</button><button class="delete" data-action="scene-remove" data-id="${e(w.scene.id)}" ${w.variants.length?'':'disabled'}>Remove scene</button></div>`;}
export const sceneFamily=w=>familyMap(allScenes(w).map(s=>({...s,mechanism:s.moments.map(m=>m.title).join(' → ')})),{action:'scene-open'});
export function fitLabel(w,s,i){return `${FITS[i.fit]}${needsReview(w,s,i)?' · review needed':''}${!i.fitReason.trim()&&i.fit!=='unchecked'?' · reason not written':''}`;}
export function comparison(w){const scenes=allScenes(w),shown=w.compareSceneIds.map(id=>scenes.find(s=>s.id===id)),ideas=[...new Map(scenes.flatMap(s=>s.ideas.map(i=>[i.id,i]))).values()];return `<section class="scene-comparison" id="scene-comparison"><div class="section-head"><div><span class="eyebrow">SAME INTERVENTION, DIFFERENT CONTEXT</span><h2>Where does it actually help?</h2><p>Compare the person, information and placement behind each judgement. A changed action is shown as another version of the intervention.</p></div></div><details id="compare-choices"><summary>Choose scenes and interventions</summary><div class="comparison-choices"><fieldset><legend>Up to four scenes</legend>${scenes.map(s=>`<label><input type="checkbox" data-action="scene-compare" data-id="${e(s.id)}" ${w.compareSceneIds.includes(s.id)?'checked':''} ${s.ancestry.parked?'disabled':''}> ${e(s.title)}${s.ancestry.parked?' · parked':''}</label>`).join('')}</fieldset><fieldset><legend>Up to four interventions</legend>${ideas.map(i=>`<label><input type="checkbox" data-action="scene-idea-compare" data-id="${e(i.id)}" ${w.compareIdeaIds.includes(i.id)?'checked':''}> ${e(i.title)}</label>`).join('')}</fieldset></div></details>${shown.length&&w.compareIdeaIds.length?`<p class="hint">Scroll sideways through scenes ↔. Open a cell to review its intervention in that scene.</p><div class="scene-comparison-scroll" tabindex="0" role="region" aria-label="Compare intervention fit across scenes"><table><thead><tr><th scope="col">Idea</th>${shown.map(s=>`<th scope="col"><button class="text-button" data-action="scene-open" data-id="${e(s.id)}">${e(s.title)}</button><p>${e(s.changed||'Original scene')}</p></th>`).join('')}</tr></thead><tbody>${w.compareIdeaIds.map(id=>{const rowIdea=ideas.find(i=>i.id===id),versions=shown.map(s=>s.ideas.find(i=>i.id===id)).filter(Boolean),different=new Set(versions.map(i=>JSON.stringify([i.action,i.assumption]))).size>1;return `<tr><th scope="row">${e(rowIdea.title)}${different?'<p class="version-note">Action or assumption varies</p>':''}</th>${shown.map(s=>{const i=s.ideas.find(i=>i.id===id),m=s.moments.find(m=>m.id===i?.momentId);return `<td>${i?`<p data-fit-scene="${e(s.id)}" data-fit-idea="${e(i.id)}" class="fit-judgement ${needsReview(w,s,i)?'stale':''}">${e(fitLabel(w,s,i))}</p><p><b>${e(i.title)}</b></p><p>${e(i.action||'Action not written.')}</p><details class="cell-context"><summary>${e(m?.title||'Unplaced')} · ${e(m?.actor||'Person not specified')}</summary><dl><dt>Knows</dt><dd>${e(m?.knows||'Not specified')}</dd><dt>Does not know</dt><dd>${e(m?.unknown||'Not specified')}</dd></dl></details><dl><dt>Fit reasoning</dt><dd>${e(i.fitReason||'Not written.')}</dd><dt>Needs</dt><dd>${e(i.fitNeeds||'Not written.')}</dd></dl><details><summary>Assumption and test</summary><p>${e(i.assumption||'Assumption not written.')}</p><p>${e(i.test||'Test not written.')}</p></details><div class="cell-actions"><button data-action="review-cell" data-scene="${e(s.id)}" data-id="${e(i.id)}">Open & review</button><button class="${w.chosenTest?.sceneId===s.id&&w.chosenTest?.ideaId===i.id?'primary':''}" data-action="scene-choose" data-scene-id="${e(s.id)}" data-id="${e(i.id)}" aria-pressed="${w.chosenTest?.sceneId===s.id&&w.chosenTest?.ideaId===i.id}">${w.chosenTest?.sceneId===s.id&&w.chosenTest?.ideaId===i.id?'Chosen test':'Choose this test'}</button></div>`:`<p>Not in this scene.</p>${w.ideas.some(i=>i.id===id)?`<button data-action="scene-copy-idea" data-id="${e(id)}" data-scene-id="${e(s.id)}">Try it here, unplaced</button>`:'<p class="hint">Open a scene containing this intervention to copy it here.</p>'}`}</td>`;}).join('')}</tr>`;}).join('')}</tbody></table></div>`:'<p>Choose scenes and interventions to compare.</p>'}${field('scene-decision','Which scene and intervention will you rehearse, and why?',w.decision,editAttrs('decision','decision','value'))}</section>`;}
